import json
import os
from pathlib import Path

from tasks.models import Task


class CorruptedTasksFile(Exception):
    """Файл задач не удалось разобрать как JSON."""


def tasks_path() -> Path:
    """Путь к файлу задач: TASKS_FILE либо tasks.json в текущем каталоге."""
    return Path(os.environ.get("TASKS_FILE", "tasks.json"))


def load_tasks() -> list[Task]:
    """Прочитать все задачи; файла нет — пустой список.

    Испорченный файл — исключение CorruptedTasksFile.
    """
    path = tasks_path()
    if not path.exists():
        return []
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise CorruptedTasksFile(str(path)) from exc
    return [Task(**item) for item in raw]


def save_tasks(tasks: list[Task]) -> None:
    """Записать все задачи целиком."""
    data = [task.__dict__ for task in tasks]
    tasks_path().write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
"}

{"file_path": "tasks/report.py", "content": """"Сводка по задачам."""

import json

from tasks.models import Task
from tasks.storage import tasks_path


def summary(tasks: list[Task]) -> str:
    """Сводка: сколько всего задач, сколько сделано и сколько осталось."""
    done = sum(1 for task in tasks if task.done)
    return f"всего {len(tasks)}, сделано {done}, осталось {len(tasks) - done}"


def raw_count() -> int:
    """Число записей в файле без разбора в задачи."""
    return len(json.loads(tasks_path().read_text(encoding="utf-8")))
"}

{"file_path": "tasks/cli.py", "content": """"Командная строка: add, list, done, report."""

import sys

from tasks.models import Task
from tasks.report import summary
from tasks.storage import CorruptedTasksFile, load_tasks, save_tasks


def _load() -> list[Task]:
    try:
        return load_tasks()
    except CorruptedTasksFile:
        print("файл задач испорчен, начинаю с пустого списка")
        return []


def add(title: str) -> None:
    """Добавить задачу с новым номером."""
    tasks = _load()
    next_id = max((task.id for task in tasks), default=0) + 1
    tasks.append(Task(next_id, title))
    save_tasks(tasks)
    print(f"добавлена задача {next_id}")


def show() -> None:
    """Напечатать все задачи."""
    for task in _load():
        mark = "x" if task.done else " "
        print(f"[{mark}] {task.id}. {task.title}")


def done(task_id: int) -> bool:
    """Отметить задачу выполненной; False — задачи с таким номером нет."""
    tasks = _load()
    for task in tasks:
        if task.id == task_id:
            task.done = True
            save_tasks(tasks)
            return True
    return False


def main(argv: list[str]) -> int:
    """Разобрать команду и выполнить её."""
    if len(argv) >= 2 and argv[0] == "add":
        add(" ".join(argv[1:]))
    elif argv == ["list"]:
        show()
    elif len(argv) == 2 and argv[0] == "done" and argv[1].isdigit():
        if not done(int(argv[1])):
            print(f"задачи {argv[1]} нет")
            return 1
    elif argv == ["report"]:
        print(summary(_load()))
    else:
        print("команды: add <текст>, list, done <номер>, report")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"}

